                params.append(f"%{search}%")
            if sort == "title":
                query += " ORDER BY title ASC"
            else:
                query += " ORDER BY id ASC"
            cur.execute(query, params)
            rows = cur.fetchall()
            return [dict(r) for r in rows]
    finally:
        conn.close()

